css:
.d-sx3{width:240px;text-align:center}
.d-success-next-sxcheck3{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--lime);color:#141a10;margin:0 auto 8px;font-size:14px}
.d-sx3 b{font-size:12.5px}
.d-sx3 p{margin:3px 0 9px;font-size:10px;color:var(--muted)}
.d-success-next-sxacts3{display:flex;gap:4px;justify-content:center;flex-wrap:wrap}
.d-success-next-sxacts3 button{font-size:9.5px;border:1px solid var(--line);background:var(--paper);border-radius:999px;padding:3px 8px;cursor:pointer}
.d-sx3 em{display:block;margin-top:8px;font:9px var(--mono);color:var(--faint);font-style:normal}

init:
root => {
    const msg = root.querySelector('[data-nextmsg3]');
    root.querySelectorAll('[data-next3]').forEach((b) => b.onclick = () => { msg.textContent = '演示：这里会打开「' + b.textContent + '」'; });
  }
